namespace Poe2Accessibility.Services
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Text.Json;

    /// <summary>
    ///     The dat columns the plugin reads, as tools/Poe2UiExtract found them in the player's own install
    ///     (catalog/dat-columns.json, regenerated by the launcher after a game patch): a column an update moved is
    ///     followed without a new build. Without the file, or for a column it lacks, the compiled offset stays, and is
    ///     judged by the one thing the file may still say of its table, the row size: a compiled offset in a table of
    ///     another size, or one nothing can judge, is reported as a part that may read wrong, not read in silence.
    /// </summary>
    public static class DatColumns
    {
        /// <summary>The part an unjudged column is reported under: its phrase is "some of the game's data, so some readings may be wrong".</summary>
        public const string UnjudgedPart = "code fields";

        private const string RowSizeSuffix = ".RowSize";

        /// <summary>Each table's row size when its compiled offsets were measured (0.5.x files, 2026-11-10, `dat-columns`).</summary>
        private static readonly Dictionary<string, int> MeasuredRowSizes = new(StringComparer.Ordinal)
        {
            ["ActiveSkills"] = 338, ["Characters"] = 640, ["GrantedEffects"] = 297, ["GrantedEffectsPerLevel"] = 116, ["MapPins"] = 202,
            ["MinimapIcons"] = 42, ["Mods"] = 693, ["PassiveSkills"] = 487, ["WorldAreas"] = 736,
        };

        private static readonly List<string> UnjudgedColumns = new();
        private static int reportedGeneration = -1;

        /// <summary>Gets the columns read at a compiled offset that nothing judged, as "Table.Column at +0x8 (why)".</summary>
        public static IReadOnlyList<string> Unjudged
        {
            get
            {
                lock (UnjudgedColumns)
                {
                    return UnjudgedColumns.ToArray();
                }
            }
        }

        /// <summary>No row is this wide (the widest read, Mods, is 0x2B5 bytes): a larger offset is a broken file.</summary>
        private const int MaxColumn = 0x1000;

        private const string PassiveName = "PassiveSkills.Name";

        /// <summary>Each column with where it was measured; a PassiveSkills column the file lacks (an older launcher) moves as far as the name did.</summary>
        private static readonly (string Column, int Measured, Action<int> Use)[] Columns =
        {
            ("Mods.Name", GameLayout.ModsDat.NameOffset, offset => GameLayout.ModsDat.NameOffset = offset),
            ("MinimapIcons.Label", GameLayout.MinimapIconRow.LabelOffset, offset => GameLayout.MinimapIconRow.LabelOffset = offset),
            ("MinimapIcons.RowSize", GameLayout.MinimapIconRow.RowSize, offset => GameLayout.MinimapIconRow.RowSize = offset),
            ("Characters.Id", GameLayout.PassiveTree.CharacterIdOffset, offset => GameLayout.PassiveTree.CharacterIdOffset = offset),
            ("Characters.Name", GameLayout.PassiveTree.CharacterNameOffset, offset => GameLayout.PassiveTree.CharacterNameOffset = offset),
            ("GrantedEffects.Id", GameLayout.SkillSlot.EffectIdOffset, offset => GameLayout.SkillSlot.EffectIdOffset = offset),
            ("ActiveSkills.DisplayedName", GameLayout.SkillSlot.DisplayedNameOffset, offset => GameLayout.SkillSlot.DisplayedNameOffset = offset),
            ("GrantedEffectsPerLevel.GrantedEffect", GameLayout.SkillSlot.EffectKeyOffset, offset => GameLayout.SkillSlot.EffectKeyOffset = offset),
            ("GrantedEffects.ActiveSkill", GameLayout.SkillSlot.SkillKeyOffset, offset => GameLayout.SkillSlot.SkillKeyOffset = offset),
            (PassiveName, GameLayout.PassiveTree.RowNameOffset, offset => GameLayout.PassiveTree.RowNameOffset = offset),
            ("PassiveSkills.GraphId", GameLayout.PassiveTree.RowGraphIdOffset, offset => GameLayout.PassiveTree.RowGraphIdOffset = offset),
            ("PassiveSkills.Characters", GameLayout.PassiveTree.RowCharactersOffset, offset => GameLayout.PassiveTree.RowCharactersOffset = offset),
            ("PassiveSkills.IsKeystone", GameLayout.PassiveTree.RowKeystoneOffset, offset => GameLayout.PassiveTree.RowKeystoneOffset = offset),
            ("PassiveSkills.IsNotable", GameLayout.PassiveTree.RowNotableOffset, offset => GameLayout.PassiveTree.RowNotableOffset = offset),
            ("PassiveSkills.IsIconOnly", GameLayout.PassiveTree.RowIconOnlyOffset, offset => GameLayout.PassiveTree.RowIconOnlyOffset = offset),
            ("PassiveSkills.IsJewelSocket", GameLayout.PassiveTree.RowJewelSocketOffset, offset => GameLayout.PassiveTree.RowJewelSocketOffset = offset),
            ("MapPins.WorldArea", GameLayout.MapPinRow.AreaKeyOffset, offset => GameLayout.MapPinRow.AreaKeyOffset = offset),
            ("MapPins.Name", GameLayout.MapPinRow.NameOffset, offset => GameLayout.MapPinRow.NameOffset = offset),
            ("MapPins.Description", GameLayout.MapPinRow.DescriptionOffset, offset => GameLayout.MapPinRow.DescriptionOffset = offset),
            ("MapPins.Content", GameLayout.MapPinRow.ContentOffset, offset => GameLayout.MapPinRow.ContentOffset = offset),
            ("WorldAreas.AreaLevel", GameLayout.WorldAreaRow.LevelOffset, offset => GameLayout.WorldAreaRow.LevelOffset = offset),
            ("WorldAreas.IsTown", GameLayout.WorldAreaRow.IsTownOffset, offset => GameLayout.WorldAreaRow.IsTownOffset = offset),
        };

        /// <summary>
        ///     Why a compiled offset of <paramref name="table"/> cannot be trusted with this file (null without one), or null
        ///     when the file says the table still has the row size the offset was measured at.
        /// </summary>
        public static string? Doubt(string table, IReadOnlyDictionary<string, int>? file)
        {
            if (file == null)
            {
                return "no dat-columns.json";
            }

            if (!MeasuredRowSizes.TryGetValue(table, out var measured) || !file.TryGetValue(table + RowSizeSuffix, out var now))
            {
                return "the file does not give the table's row size";
            }

            return now == measured ? null : $"the table's rows are 0x{now:X} bytes, 0x{measured:X} when it was measured";
        }

        /// <summary>Says the unjudged columns once per game process, through the report the plugin already speaks.</summary>
        public static void Report(CompatibilityReport? report)
        {
            if (report == null || report.Generation == reportedGeneration)
            {
                return;
            }

            reportedGeneration = report.Generation;
            if (Unjudged.Count > 0)
            {
                report.Missing(UnjudgedPart);
            }
        }

        /// <returns>The columns of the file, null without one, for the host structs that read them.</returns>
        public static IReadOnlyDictionary<string, int>? Apply(string path, PluginLog log)
        {
            lock (UnjudgedColumns)
            {
                UnjudgedColumns.Clear();
                reportedGeneration = -1;
            }

            Dictionary<string, int>? columns = null;
            try
            {
                columns = File.Exists(path) ? JsonSerializer.Deserialize<Dictionary<string, int>>(File.ReadAllText(path)) : null;
            }
            catch (Exception exception) when (exception is IOException or JsonException or UnauthorizedAccessException)
            {
                log.Warn($"Dat columns unreadable ({exception.Message}): read where measured");
            }

            var nameShift = 0;
            foreach (var (column, measured, use) in Columns)
            {
                var fallback = column.StartsWith("PassiveSkills.", StringComparison.Ordinal) ? measured + nameShift : measured;
                var offset = 0;
                if (columns == null || !columns.TryGetValue(column, out offset) || offset is < 0 or >= MaxColumn)
                {
                    use(fallback);
                    Fallback(column, fallback, fallback != measured ? "moved with the table's name column, a guess" : Doubt(column[..column.IndexOf('.')], columns), log);
                    continue;
                }

                use(offset);
                nameShift = column == PassiveName ? offset - measured : nameShift;
                log.Info(offset == measured ? $"Dat columns: {column} where measured" : $"Dat columns: {column} moved from +0x{measured:X} to +0x{offset:X}");
            }

            return columns;
        }

        private static void Fallback(string column, int offset, string? doubt, PluginLog log)
        {
            if (doubt == null)
            {
                log.Info($"Dat columns: {column} not in the file, read at +0x{offset:X} (its table has the row size it was measured at)");
                return;
            }

            log.Warn($"Dat columns: {column} read at its compiled offset +0x{offset:X}, which nothing judged ({doubt})");
            lock (UnjudgedColumns)
            {
                UnjudgedColumns.Add($"{column} at +0x{offset:X} ({doubt})");
            }
        }
    }
}
